export function createPointRouteFetchHandler() {
  return async (req) => {
    const url = new URL(req.url);
  if (req.method === "GET" && new RegExp("^\\/api\\/health$").test(url.pathname)) {
    const match = url.pathname.match(new RegExp("^\\/api\\/health$"));
    const handlerResult = healthCheckRoute();
    return pointRouteResponse(await handlerResult);
  }
  if (req.method === "POST" && new RegExp("^\\/api\\/login$").test(url.pathname)) {
    const match = url.pathname.match(new RegExp("^\\/api\\/login$"));
    const bodyRecord = await pointBodyRecord(req, ["email","password"]);
    {
      const middlewareResult = rejectInvalidLoginMiddleware(bodyRecord);
      if (middlewareResult != null) return pointRouteResponse(middlewareResult, { status: 401 });
    }
    const handlerResult = loginRoute(bodyRecord);
    return pointRouteResponse(await handlerResult);
  }
  if (req.method === "GET" && new RegExp("^\\/api\\/members$").test(url.pathname)) {
    const match = url.pathname.match(new RegExp("^\\/api\\/members$"));
    const handlerResult = listMembersRoute();
    return pointRouteResponse(await handlerResult);
  }
  if (req.method === "POST" && new RegExp("^\\/api\\/members$").test(url.pathname)) {
    const match = url.pathname.match(new RegExp("^\\/api\\/members$"));
    const headerRecord = pointHeaderRecord(req.headers, ["authorization"]);
    const bodyRecord = await pointBodyRecord(req, ["name","role"]);
    {
      const middlewareResult = requireAuthMiddleware(headerRecord);
      if (middlewareResult != null) return pointRouteResponse(middlewareResult, { status: 401 });
    }
    const handlerResult = createMemberRoute(headerRecord, bodyRecord);
    return pointRouteResponse(await handlerResult);
  }
    return new Response(JSON.stringify({ error: "Not found" }), { status: 404, headers: { "content-type": "application/json" } });
  };
}

